mapper.select:
SELECT COUNT(*)
  FROM analysis_file_pass
 WHERE revision_id = #{revisionId}
   AND pass = #{pass}
AND status = #{status}

mapper.update:
UPDATE analysis_file_pass
   SET status = #{status}
     , error_message = #{errorMessage}
     , carried = FALSE
     , updated_at = now()
 WHERE file_id = #{fileId}
   AND pass = #{pass}
